import type { APIRequest, TransportConnectionParams } from '@pipecat-ai/client-js';

export type TransportType = 'daily' | 'smallwebrtc' | 'websocket';

export const AVAILABLE_TRANSPORTS: TransportType[] = [
  'daily',
  'smallwebrtc',
];

export const TRANSPORT_LABELS: Record<TransportType, string> = {
  daily: 'Daily',
  smallwebrtc: 'SmallWebRTC',
  websocket: 'WebSocket',
};

export const DEFAULT_TRANSPORT: TransportType = 'daily';

const DEFAULT_AGENT = 'car-support-agent';
const KEY_STORAGE = 'pipecat-cloud-public-key';

// ?agent=<name> points the page at another Pipecat Cloud agent.
const agent =
  new URLSearchParams(window.location.search).get('agent') || DEFAULT_AGENT;
const cloudStartUrl = `https://api.pipecat.daily.co/v1/public/${encodeURIComponent(agent)}/start`;

// `npm run dev` talks to the local bot. A built page (GitHub Pages) talks to
// Pipecat Cloud. VITE_BOT_START_URL overrides both.
const botStartUrl =
  import.meta.env.VITE_BOT_START_URL ||
  (import.meta.env.DEV ? 'http://localhost:7860/start' : cloudStartUrl);

function saveKey(key: string) {
  try {
    localStorage.setItem(KEY_STORAGE, key);
  } catch {
    // Storage can be blocked (private window). The key still works for this visit.
  }
}

// The key comes from the link (#key=pk_...), or from the last visit, or from
// VITE_BOT_START_PUBLIC_API_KEY. A key in the link wins. It sits after the "#"
// so it is never sent to a server, and it is wiped from the URL bar once read
// so it does not show in a screen share. There is no box to type it in.
function readInitialKey(): string {
  const hash = new URLSearchParams(window.location.hash.slice(1));
  const fromLink = hash.get('key');
  if (fromLink) {
    saveKey(fromLink);
    hash.delete('key');
    const rest = hash.toString();
    history.replaceState(
      null,
      '',
      window.location.pathname +
        window.location.search +
        (rest ? `#${rest}` : '')
    );
    return fromLink;
  }
  let stored = '';
  try {
    stored = localStorage.getItem(KEY_STORAGE) ?? '';
  } catch {
    // Fall through to the build-time key.
  }
  return stored || import.meta.env.VITE_BOT_START_PUBLIC_API_KEY || '';
}

// The Pipecat Cloud public key is sent as a Bearer token. A local bot needs
// no key, so the header is left off when there is none.
const publicKey = readInitialKey().trim();
const headers = publicKey
  ? new Headers({ Authorization: `Bearer ${publicKey}` })
  : undefined;

export type LlmChoice = 'openai' | 'gemini';

export const LLM_LABELS: Record<LlmChoice, string> = {
  gemini: 'Gemini',
  openai: 'OpenAI',
};

export const DEFAULT_LLM: LlmChoice = 'gemini';

export type VoiceChoice = 'flux-sharon-en' | 'aura-2-theia-en';

export const VOICE_LABELS: Record<VoiceChoice, string> = {
  'flux-sharon-en': 'Sharon',
  'aura-2-theia-en': 'Theia',
};

export const DEFAULT_VOICE: VoiceChoice = 'flux-sharon-en';

// Sent to the bot as the start request's `body`. Like `headers`, it is one
// object changed in place, so picking an option does not rebuild the client.
const startBody: { llm: LlmChoice; voice: VoiceChoice } = {
  llm: DEFAULT_LLM,
  voice: DEFAULT_VOICE,
};

/** Use this LLM for the next call. */
export function setLlm(llm: LlmChoice) {
  startBody.llm = llm;
}

/** Use this voice for the next call. */
export function setVoice(voice: VoiceChoice) {
  startBody.voice = voice;
}

const dailyConfig: APIRequest = {
  endpoint: botStartUrl,
  headers,
  requestData: {
    createDailyRoom: true,
    dailyRoomProperties: { start_video_off: true },
    transport: 'daily',
    body: startBody,
  },
};

const smallWebRTCConfig: APIRequest = {
  endpoint: botStartUrl,
  headers,
  requestData: {
    createDailyRoom: false,
    enableDefaultIceServers: true,
    transport: 'webrtc',
    body: startBody,
  },
};

const websocketConfig: APIRequest = {
  endpoint: botStartUrl,
  headers,
  requestData: {
    transport: 'websocket',
  },
};

/**
 * Append the connection token (if any) to the WebSocket URL returned by the
 * server before the transport connects.
 */
const websocketResponseTransformer = (
  response: TransportConnectionParams
): TransportConnectionParams => {
  const { wsUrl, token } = response as { wsUrl: string; token?: string };
  return {
    wsUrl: token ? `${wsUrl}?token=${encodeURIComponent(token)}` : wsUrl,
  };
};

/**
 * Props passed to `PipecatAppBase` for each transport. WebRTC transports
 * connect in one step via `connectParams`; WebSocket starts the bot first and
 * transforms the response into the WebSocket connection params.
 */
export interface TransportProps {
  connectParams?: APIRequest | TransportConnectionParams;
  startBotParams?: APIRequest;
  startBotResponseTransformer?: (
    response: TransportConnectionParams
  ) => TransportConnectionParams | Promise<TransportConnectionParams>;
}

export const TRANSPORT_PROPS: Record<TransportType, TransportProps> = {
  daily: { connectParams: dailyConfig },
  smallwebrtc: { connectParams: smallWebRTCConfig },
  websocket: {
    startBotParams: websocketConfig,
    startBotResponseTransformer: websocketResponseTransformer,
  },
};